/* A distinct illustrative architectural identity for every factory. */
const factoryArchitecture=[
{src:'assets/factory-detailed-campus.png',style:'Connected manufacturing campus',positions:{'Workforce Mgmt':[26,65],Quality:[17,35],Process:[46,23],Packaging:[72,34],Facility:[82,14],Maintenance:[76,64]}},
{src:'assets/factory-delta-campus.png',style:'Courtyard manufacturing campus',positions:{'Workforce Mgmt':[23,58],Quality:[30,32],Process:[48,18],Packaging:[74,44],Facility:[86,23],Maintenance:[71,67]}},
{src:'assets/factory-alexandria-campus.png',style:'Coastal biologics research campus',positions:{'Workforce Mgmt':[49,68],Quality:[19,55],Process:[40,26],Packaging:[76,43],Facility:[83,18],Maintenance:[84,61]}},
{src:'assets/factory-suez-campus.png',style:'High-capacity industrial campus',positions:{'Workforce Mgmt':[18,27],Quality:[21,57],Process:[46,28],Packaging:[73,44],Facility:[83,17],Maintenance:[70,70]}}
];
function architectureFor(i=factoryIndex()){return factoryArchitecture[i]||factoryArchitecture[0]}
window.currentFactoryModelVariant=()=>factoryIndex();
siteMiniature=function(index=0){return `<img class="terrain-miniature" src="${architectureFor(index).src}" alt="Illustrative 3D campus: ${escapeHTML(factories[index]?.name||'Factory')}">`};
const networkBeforeIdentities=terrainNetwork;terrainNetwork=function(){const wrapper=document.createElement('div');wrapper.innerHTML=networkBeforeIdentities();wrapper.querySelectorAll('.terrain-site-row img').forEach((img,i)=>{img.setAttribute('src',architectureFor(i).src);img.setAttribute('alt','Illustrative 3D campus: '+factories[i].name);img.classList.add('factory-variant-thumb')});const selected=wrapper.querySelector('.terrain-campus');if(selected){selected.setAttribute('src',architectureFor(terrainSelection).src);selected.setAttribute('alt','Illustrative 3D campus: '+factories[terrainSelection].name);selected.classList.add('terrain-campus-3d')}return wrapper.innerHTML};
const smartViewBeforeIdentities=smartFactoryView;smartFactoryView=function(){const art=architectureFor(),wrapper=document.createElement('div');wrapper.innerHTML=smartViewBeforeIdentities();const img=wrapper.querySelector('.smart-campus-scene>img');if(img){img.setAttribute('src',art.src);img.setAttribute('alt',factories[factoryIndex()].name+' · '+art.style+' · Illustrative 3D design')}const label=wrapper.querySelector('.smart-view-options>span');if(label)label.innerHTML='<i class="smart-pulse"></i> '+art.style.toUpperCase();return wrapper.innerHTML};
enlargeSmartCampus=function(){const art=architectureFor();openModal(factories[factoryIndex()].name+' · Campus view',`<div class="smart-campus-enlarged"><img src="${art.src}" alt="${escapeHTML(art.style)}"></div><div class="scope-label">${art.style} · Illustrative architectural design</div><div class="actions">${campusAreas.map(a=>opButton(a.name,`$('#modal').close();chooseSmartArea('${a.id}')`)).join('')}</div>`);$('#modal').classList.add('wide-modal','equipment-modal')};
let lastArchitecturalFactory=-1;
const renderBeforeFactoryIdentities=render;render=function(){const current=factoryIndex(),art=architectureFor(current);if(lastArchitecturalFactory!==current){smartZoom=1;smartPan={x:0,y:0};lastArchitecturalFactory=current}for(const area of campusAreas){const position=art.positions[area.id];if(position){area.x=position[0];area.y=position[1]}}renderBeforeFactoryIdentities()};
render();
